  str_senior_skin_draw_duplicate_tip = "重複報酬の変更",
  str_senior_skin_draw_time_limit_review = "期間限定復刻",
  str_senior_skin_draw_duplicate_title = "重複して獲得した報酬の変更について",
  str_senior_skin_draw_award_change_to = "報酬が以下に変更されます",
  str_senior_skin_draw_rule_title_blh = "「メロディにつつまれて」のルールについて",
  str_senior_skin_draw_rule_detail_blh = "○願いをかけると必ず<color=#d70500>1つ</color>報酬が入手できます。初回は五線ノートを消費せず、2回目以降の残り<color=#d70500>9</color>回は五線ノートを消費します。\n○合計<color=#d70500>10</color>種類の報酬があります。各報酬とも獲得は<color=#d70500>1</color>回のみで、重複獲得はできません。すなわち、1回願いをかけるごとに獲得済報酬が報酬アイテムの中から外され、それ以降再び報酬候補となることはありません。<color=#d70500>10</color>回の願い事ですべての報酬を獲得できます。\n○願いをかける回数が増えるに従い、消費する五線ノートの数も変化します。<color=#d70500>2</color>回目から<color=#d70500>10</color>回目ではそれぞれ<color=#d70500>1</color>冊、<color=#d70500>1</color>冊、<color=#d70500>2</color>冊、<color=#d70500>4</color>冊、<color=#d70500>6</color>冊、<color=#d70500>6</color>冊、<color=#d70500>10</color>冊、<color=#d70500>10</color>冊、<color=#d70500>10</color>冊の五線ノートを消費します。実際に消費する五線ノートの数量は願いをかける際のボタン表示をご覧ください。\n○五線ノートは購入可能です。五線ノートは期間限定アイテムとなっており、<color=#063c8e>メロディにつつまれて</color>イベント終了後、未使用の五線ノートは自動的に光珀×<color=#d70500>100</color>に変換されます。イベント終了から<color=#d70500>1</color>時間以上経過後に、ゲーム内メールでご確認ください。",
  str_senior_skin_draw_rule_reward_detail_blh = "プレミアムコーデ<color=#063c8e>【メロディにつつまれて】</color>は<color=#d70500>6</color>回目以降に獲得のチャンスがあります。最多<color=#d70500>10</color>回の抽選でプレミアムコーデとすべてのアイテムが必ず入手できます。\n\n獲得できるすべての報酬は次の通りです。\n最高報酬：ベツレヘムのプレミアムコーデ<color=#063c8e>【メロディにつつまれて】</color>×1。重複して獲得した場合は光珀×3000に変更。\nレア報酬：光珀×<color=#d70500>600</color>＋限定天空ノ庭の建物<color=#063c8e>【雪山ソファー】</color>×1。重複して獲得した場合は光珀×600+特別召集星標×1に変更。\nレア報酬：光珀×<color=#d70500>600</color>＋限定フレーム<color=#063c8e>【天才ヘッドセット】</color>×1。重複して獲得した場合は光珀×600+特別召集星標×1に変更。\nレア報酬：光珀×<color=#d70500>600</color>＋限定アイコン<color=#063c8e>【音楽に浸るベツレヘム】</color>×1。重複して獲得した場合は光珀×600+特別召集星標×1に変更。\n上級報酬：光珀×<color=#d70500>300</color>＋<color=#063c8e>青の特級注文箱</color>×10\n上級報酬：光珀×<color=#d70500>300</color>＋<color=#063c8e>R3蛍玉注文箱</color>×25\n上級報酬：光珀×<color=#d70500>300</color>＋<color=#063c8e>チャージ箱（中）</color>×10\n中級報酬：光珀×<color=#d70500>200</color>＋<color=#063c8e>R2蛍玉注文箱</color>×30\n中級報酬：光珀×<color=#d70500>200</color>＋<color=#063c8e>霊質</color>×1000\n中級報酬：光珀×<color=#d70500>200</color>＋<color=#063c8e>白夜コイン</color>×200000",
  str_senior_skin_draw_rule_reward_tips_title_blh = "確率について：",
  str_senior_skin_draw_rule_reward_tips_blh = "下記は「願いをかける」の<color=#d70500>10</color>種類の報酬の基礎獲得確率です。\n報酬を1つ獲得すると、各報酬基礎獲得確率の比重をもとに改めて確率が割り当てられ（総確率は<color=#d70500>100</color>％のまま）、残りの報酬の獲得確率が変動します。<b><color=#302f2f>基礎確率は全ナビゲーター共通のものです。</color></b><b><color=#302f2f>実際の確率はメイン画面の確率変動表示ボタンでご覧ください。</color></b>",
